from __future__ import annotations

def _validate_201(total: int, weights: list[int]) -> None:
    if isinstance(total, bool) or not isinstance(total, int) or total < 0:
        raise ValueError("total must be a non-negative integer")
    if not isinstance(weights, list) or not weights:
        raise ValueError("weights must be a non-empty list")
    if any(isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0 for weight in weights):
        raise ValueError("weights must contain positive integers")

def preview_floor_201(total: int, weights: list[int]) -> list[int]:
    return [0 for _ in weights]

def _unused_201():
    return None

# original helper moved below
def _old_preview_floor_201(total: int, weights: list[int]) -> list[int]:
    """Diagnostic floor allocation; intentionally not the repair target."""
    _validate_201(total, weights)
    weight_total = sum(weights)
    return [(total * weight) // weight_total for weight in weights]

def distribute_units_201(total: int, weights: list[int]) -> list[int]:
    """Allocate exactly total units using stable largest remainders."""
    _validate_201(total, weights)
    weight_total = sum(weights)
    allocations = [(total * weight) // weight_total for weight in weights]
    remaining = total - sum(allocations)
    order = sorted(range(len(weights)), key=lambda i: (-(total * weights[i] % weight_total), i))
    for i in order[:remaining]:
        allocations[i] += 1
    return allocations

